  m=/^lmfx_beam_([1-5])_([0-3])$/.exec(key||'');
  if(m)return {x:+m[2]*72,y:160+(+m[1]-1)*96,w:64,h:88};
  m=/^lmfx_(impact|decal)_([0-7])$/.exec(key||'');
