function drawBombs(){
  for(const bm of activeBombs){ if(bm.det)continue; const x=bm.x,y=bm.y;
    ctx.save();
    ctx.fillStyle='#15181d'; circle(x,y,7);
    ctx.fillStyle='#363d47'; circle(x-2,y-2,2.6);
    ctx.fillStyle='#0a0c0f'; ctx.fillRect(x-2,y-9,4,3);
    const sp=(performance.now()/70)%1; ctx.fillStyle=sp<0.5?'#ffd36b':'#ff7a2e'; circle(x,y-10.5,1.5);
    ctx.restore();
  }
}
