/* Optional external UI layout override, written by the BOF UI Editor tool.
   Loaded once at boot; if missing/blocked (e.g. opened via file:// with no local server)
   the game silently keeps its built-in menu layouts — this is a pure enhancement, never required. */
let UI_LAYOUT_OVERRIDE=null;
(function loadUILayout(){
  try{
    /* DO NOT EVEN TRY ON file:// (drop 0801ex). Mike: "I dont want to have to run
       a server to run this game."

       He does not have to, and never did. This fetch is a pure enhancement - an
       optional layout override written by the UI editor tool - it is wrapped in
       catch, and the file is not even shipped. The game keeps its built-in menu
       layouts either way.

       But on file:// the browser refuses the request and logs a red CORS error
       before our catch ever sees it, which sits in the console looking like a
       fault. Checking the protocol first means the request is never made, so
       there is nothing to log.

       Nothing else in the build needs http: no other fetch, no XMLHttpRequest,
       no dynamic import, no module scripts. index.html loads manifest.js and
       game.js with plain <script src>, which file:// serves happily. */
    if(typeof fetch!=='function') return;
    if(typeof location!=='undefined' && location.protocol==='file:') return;
    fetch('assets/data/ui_layout.json',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(d=>{ if(d) UI_LAYOUT_OVERRIDE=d; }).catch(()=>{});
  }catch(e){}
})();
function uiRect(screenKey, elKey, fallback){
  const o=UI_LAYOUT_OVERRIDE && UI_LAYOUT_OVERRIDE[screenKey] && UI_LAYOUT_OVERRIDE[screenKey][elKey];
  return o ? {x:o.x,y:o.y,w:o.w,h:o.h} : fallback;
}
let flyoverT=0, flyoverScroll=0, flyoverStartX=0, flyoverStartY=0;
