    add(37.80,()=>{spawnEnemy('s9prism',W9*.32,-132,{_s9Role:'beam'});spawnEnemy('s9beacon',W9*.68,-126,{_s9Role:'orb',_stagger:.17});spawnEnemy('s9comet',-86,VH*.18,{_side:1,_s9Role:'slider',_stagger:.30});});
