      for(let i=0;i<8;i++)if(XART._touch)XART._touch(fam+'_'+i);
    for(let i=0;i<8;i++){
      if(XART._touch)XART._touch('nxp_dense_'+i);
      if(typeof SMOKE_FAM!=='undefined'&&XART._touch)XART._touch(SMOKE_FAM+'_'+i);
    }
