            for(let lane=0; lane<3; lane++){
              const lx=W6*(0.20+lane*0.30) + Math.sin((b.t||0)*1.3+lane)*W6*0.06;
              for(let k=0;k<7;k++) eShoot(lx, b.y+b.h*0.24+k*16, Math.PI/2, 3.1+k*0.12, 'bolt');
            }
            if(typeof atomFlash!=='undefined') atomFlash=Math.max(atomFlash,0.30);
            shake=Math.max(shake,7);
