  el_jh   :{p:'mba_jh',  c:'mod5', w:44,h:44, hp:16, sc:1000, fr:1.3},   // jungle hornet  -> L1
  el_em   :{p:'mba_em',  c:'mod5', w:44,h:44, hp:16, sc:1000, fr:1.3},   // ember mantis   -> L2
  el_cs   :{p:'mba_cs',  c:'mod5', w:44,h:44, hp:16, sc:1000, fr:1.3},   // cryo scarab    -> L3
