  const rdy=(k)=>typeof XART!=='undefined'&&XART.rdy(k);

  // ===== CAMPAIGN BOOT: terminal -> FLASH -> borderless map (zoomed in) -> border LOCKS
  // (camera pulls back so the baked frame sweeps in) -> flags drop 1-by-1 -> retina sweeps
  // each flag with sounds -> lock on the playable flag -> menu music. =====
  drawStageSelect._cam={z:1, ax:VW/2, ay:MY+240*S};   // camera: zoom + anchor (screen coords)
  const _easeOutCubic=(x)=>1-Math.pow(1-x,3);
