    ctx.lineWidth=3; ctx.strokeStyle='rgba(0,0,0,0.7)'; ctx.strokeText(label,bx+bw2/2,by+bh2/2);
    ctx.fillStyle=hot?'#ffffff':col; ctx.fillText(label,bx+bw2/2,by+bh2/2);
