    drawLaunch._pt+=dt; drawLaunch._spd=(run.stage===5?STAGE5_SPACE_CRUISE:LAUNCH_COUNTDOWN_SCROLL);
    const _rng=(typeof levelScrollRange==='function')?levelScrollRange():0;
